// valibot 1.1.0's API as tests/typescript/modules/npm-valibot uses it,
// written for the test: the package's own index.d.ts is 590 KB
export interface Issue {
	readonly kind: string;
	readonly type: string;
	readonly message: string;
	readonly path?: ReadonlyArray<{readonly key: unknown}>;
}
export interface Schema<T> {
	readonly kind: "schema";
	readonly type: string;
	readonly "~types"?: {readonly output: T};
}
export interface Action {
	readonly kind: "validation" | "transformation";
	readonly type: string;
}
export type InferOutput<S> = S extends Schema<infer T> ? T : never;
export type SafeParseResult<T> =
	| {readonly success: true; readonly output: T; readonly issues: undefined}
	| {readonly success: false; readonly output: unknown; readonly issues: [Issue, ...Array<Issue>]};
export declare function string(message?: string): Schema<string>;
export declare function number(message?: string): Schema<number>;
export declare function boolean(message?: string): Schema<boolean>;
export declare function array<T>(item: Schema<T>, message?: string): Schema<Array<T>>;
export declare function optional<T>(wrapped: Schema<T>): Schema<T | undefined>;
export declare function picklist<const T extends ReadonlyArray<string>>(options: T, message?: string): Schema<T[number]>;
export declare function object<E extends Record<string, Schema<unknown>>>(entries: E, message?: string): Schema<{[K in keyof E]: InferOutput<E[K]>}>;
export declare function pipe<T>(schema: Schema<T>, ...actions: Array<Action>): Schema<T>;
export declare function minLength(requirement: number, message?: string): Action;
export declare function maxLength(requirement: number, message?: string): Action;
export declare function minValue(requirement: number, message?: string): Action;
export declare function integer(message?: string): Action;
export declare function email(message?: string): Action;
export declare function emoji(message?: string): Action;
export declare function trim(): Action;
export declare function safeParse<T>(schema: Schema<T>, input: unknown): SafeParseResult<T>;
export declare function parse<T>(schema: Schema<T>, input: unknown): T;
export declare function is<T>(schema: Schema<T>, input: unknown): input is T;
export declare class ValiError extends Error {
	readonly issues: [Issue, ...Array<Issue>];
}
